CREATE OR REPLACE FUNCTION public.review_indicator_request(p_actor uuid,p_id uuid,p_status text) RETURNS public.indicator_requests LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_row public.indicator_requests; v_email text; BEGIN
 IF p_actor IS DISTINCT FROM '27be6c2d-ce77-425b-bc69-53026daf099b'::uuid OR NOT public.has_role(p_actor,'admin') THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
 IF p_status IS NULL OR p_status NOT IN ('approved','rejected') THEN RAISE EXCEPTION 'Invalid decision'; END IF;
 SELECT * INTO v_row FROM public.indicator_requests WHERE id=p_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Request not found'; END IF;
 IF v_row.status=p_status THEN RETURN v_row; END IF; IF v_row.status<>'pending' THEN RAISE EXCEPTION 'Request already reviewed'; END IF;
 IF p_status='approved' THEN
 SELECT email INTO v_email FROM auth.users WHERE id=v_row.user_id AND (banned_until IS NULL OR banned_until<now());
 IF NOT FOUND OR NOT (public.has_role(v_row.user_id,'admin') OR public.has_role(v_row.user_id,'shlm_mod') OR public.has_role(v_row.user_id,'free_member') OR public.has_role(v_row.user_id,'recruiter') OR EXISTS(SELECT 1 FROM public.purchases WHERE status='paid' AND (user_id=v_row.user_id OR email=v_email))) THEN RAISE EXCEPTION 'Member no longer eligible'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.indicators WHERE id=v_row.indicator_id AND active) THEN RAISE EXCEPTION 'Indicator archived'; END IF;
 END IF;
 UPDATE public.indicator_requests SET status=p_status,reviewed_by=p_actor,reviewed_at=now() WHERE id=p_id RETURNING * INTO v_row; RETURN v_row; END $$;
REVOKE ALL ON FUNCTION public.review_indicator_request(uuid,uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.review_indicator_request(uuid,uuid,text) TO service_role;
CREATE TABLE public.bible_memberships(user_id uuid PRIMARY KEY, joined_at timestamptz NOT NULL DEFAULT now(), active boolean NOT NULL DEFAULT true, muted_until timestamptz, blocked boolean NOT NULL DEFAULT false, notifications boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.bible_memberships TO authenticated; GRANT ALL ON public.bible_memberships TO service_role;
ALTER TABLE public.bible_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY bible_membership_own ON public.bible_memberships FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.is_bible_member() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.bible_memberships WHERE user_id=auth.uid() AND active AND NOT blocked) $$;
REVOKE ALL ON FUNCTION public.is_bible_member() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.is_bible_member() TO authenticated,service_role;
CREATE TABLE public.bible_teachings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text NOT NULL DEFAULT '', scripture text NOT NULL DEFAULT '', video_path text, thumbnail_path text, state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','uploading','processing','ready','failed')), published boolean NOT NULL DEFAULT false, featured boolean NOT NULL DEFAULT false, duration_seconds numeric, media_type text, file_size bigint, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.bible_teachings TO authenticated; GRANT ALL ON public.bible_teachings TO service_role;
ALTER TABLE public.bible_teachings ENABLE ROW LEVEL SECURITY;
CREATE POLICY bible_teachings_read ON public.bible_teachings FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR (public.is_bible_member() AND published AND state='ready'));
CREATE TABLE public.bible_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, author_name text NOT NULL, body text NOT NULL CHECK(char_length(body) BETWEEN 1 AND 2000), reply_to uuid REFERENCES public.bible_messages(id), submission_id uuid NOT NULL, pinned boolean NOT NULL DEFAULT false, removed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,submission_id));
GRANT SELECT ON public.bible_messages TO authenticated; GRANT ALL ON public.bible_messages TO service_role;
ALTER TABLE public.bible_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY bible_messages_read ON public.bible_messages FOR SELECT TO authenticated USING(public.is_bible_member() AND (NOT removed OR public.has_role(auth.uid(),'admin')));
CREATE INDEX bible_messages_time ON public.bible_messages(created_at DESC);
CREATE TABLE public.bible_reactions(message_id uuid REFERENCES public.bible_messages(id) ON DELETE CASCADE, user_id uuid NOT NULL, reaction text NOT NULL CHECK(reaction IN ('heart','amen','pray')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(message_id,user_id,reaction));
GRANT SELECT ON public.bible_reactions TO authenticated; GRANT ALL ON public.bible_reactions TO service_role;
ALTER TABLE public.bible_reactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY bible_reactions_read ON public.bible_reactions FOR SELECT TO authenticated USING(public.is_bible_member() AND EXISTS(SELECT 1 FROM public.bible_messages WHERE id=message_id AND NOT removed));
CREATE TABLE public.bible_notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, message_id uuid REFERENCES public.bible_messages(id) ON DELETE CASCADE, body text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,message_id));
GRANT SELECT,UPDATE ON public.bible_notifications TO authenticated; GRANT ALL ON public.bible_notifications TO service_role;
ALTER TABLE public.bible_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY bible_notifications_own ON public.bible_notifications FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.is_bible_member());
CREATE POLICY bible_notifications_mark ON public.bible_notifications FOR UPDATE TO authenticated USING(user_id=auth.uid() AND public.is_bible_member()) WITH CHECK(user_id=auth.uid() AND public.is_bible_member());
CREATE FUNCTION public.send_bible_message(p_user uuid,p_name text,p_body text,p_reply uuid,p_submission uuid) RETURNS public.bible_messages LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_member public.bible_memberships; v_row public.bible_messages; v_parent public.bible_messages; BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text||':bible-chat',0));
 SELECT * INTO v_member FROM public.bible_memberships WHERE user_id=p_user FOR UPDATE;
 IF NOT FOUND OR NOT v_member.active OR v_member.blocked OR v_member.muted_until>now() THEN RAISE EXCEPTION 'Chat membership required or posting restricted' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_row FROM public.bible_messages WHERE user_id=p_user AND submission_id=p_submission; IF FOUND THEN IF v_row.body IS DISTINCT FROM btrim(p_body) OR v_row.reply_to IS DISTINCT FROM p_reply THEN RAISE EXCEPTION 'Submission already used'; END IF; RETURN v_row; END IF;
 IF char_length(btrim(p_body)) NOT BETWEEN 1 AND 2000 OR p_submission IS NULL THEN RAISE EXCEPTION 'Invalid message'; END IF;
 IF (SELECT count(*) FROM public.bible_messages WHERE user_id=p_user AND created_at>now()-interval '1 minute')>=10 THEN RAISE EXCEPTION 'Please wait before sending another message'; END IF;
 IF p_reply IS NOT NULL THEN SELECT * INTO v_parent FROM public.bible_messages WHERE id=p_reply AND NOT removed; IF NOT FOUND THEN RAISE EXCEPTION 'Reply unavailable'; END IF; END IF;
 INSERT INTO public.bible_messages(user_id,author_name,body,reply_to,submission_id) VALUES(p_user,left(COALESCE(p_name,'Member'),100),btrim(p_body),p_reply,p_submission) RETURNING * INTO v_row;
 IF p_reply IS NOT NULL AND v_parent.user_id<>p_user THEN INSERT INTO public.bible_notifications(user_id,message_id,body) SELECT v_parent.user_id,v_row.id,left(p_name||' replied to you',200) WHERE EXISTS(SELECT 1 FROM public.bible_memberships WHERE user_id=v_parent.user_id AND active AND NOT blocked AND notifications) ON CONFLICT DO NOTHING; END IF;
 RETURN v_row; END $$;
REVOKE ALL ON FUNCTION public.send_bible_message(uuid,text,text,uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.send_bible_message(uuid,text,text,uuid,uuid) TO service_role;
CREATE TRIGGER bible_memberships_updated BEFORE UPDATE ON public.bible_memberships FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER bible_teachings_updated BEFORE UPDATE ON public.bible_teachings FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER bible_messages_updated BEFORE UPDATE ON public.bible_messages FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
ALTER PUBLICATION supabase_realtime ADD TABLE public.bible_messages,public.bible_reactions,public.bible_notifications,public.bible_memberships,public.bible_teachings;